// 临时 vitest shim（仅本机验证用，跑完即删）。
export const _tests = [];
export const _afterEaches = [];

export function describe(_name, fn) { fn(); }
export function it(name, fn) { fn.name = name; _tests.push(fn); }
export function afterEach(fn) { _afterEaches.push(fn); }

function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (a && b && typeof a === "object") {
    if (Array.isArray(a) !== Array.isArray(b)) return false;
    const ka = Object.keys(a), kb = Object.keys(b);
    if (ka.length !== kb.length) return false;
    return ka.every((k) => deepEqual(a[k], b[k]));
  }
  return false;
}

function makeMatcher(actual) {
  const check = (cond, msg) => { if (!cond) throw new Error("EXPECT FAILED: " + msg); };
  return {
    toBe: (e) => check(actual === e, `${JSON.stringify(actual)} toBe ${JSON.stringify(e)}`),
    toEqual: (e) => check(deepEqual(actual, e), `${JSON.stringify(actual)} toEqual ${JSON.stringify(e)}`),
    toBeNull: () => check(actual === null, `${JSON.stringify(actual)} toBeNull`),
    toBeCloseTo: (e, digits = 2) => {
      const tol = 0.5 * Math.pow(10, -digits);
      check(Math.abs(actual - e) < tol, `${actual} close to ${e} (digits ${digits})`);
    },
    toBeGreaterThanOrEqual: (e) => check(actual >= e, `${actual} >= ${e}`),
  };
}
export function expect(actual) { return makeMatcher(actual); }

